<script>document.getElementById("erp-billing-form")?.addEventListener("submit",function(e){const selected=this.querySelectorAll(".erp-entry-check:checked").length;if(selected===0){e.preventDefault();alert("Bitte mindestens einen Zeiteintrag auswählen.");return;}const status=this.querySelector("select[name=billingStatus]")?.value;const ref=this.querySelector("input[name=billingReference]")?.value.trim();if(status==="billed"&&!ref){e.preventDefault();alert("Bitte eine Abrechnungsreferenz eintragen.");}});</script>
